CREATE OR REPLACE FUNCTION "public"."check_agent_instance_can_update"(
    p_subject_type TEXT,
    p_subject_id TEXT,
    p_object_id TEXT,
    p_visited TEXT [] DEFAULT ARRAY[]::TEXT[]
) RETURNS INTEGER AS $$
DECLARE
    v_has_access BOOLEAN := FALSE;
    v_key TEXT := 'agent_instance:' || p_object_id || ':can_update';
    v_userset_check INTEGER := 0;
BEGIN
    -- Cycle detection
    IF v_key = ANY(p_visited) THEN
        RETURN 0;
    END IF;
    IF array_length(p_visited, 1) >= 25 THEN
        RAISE EXCEPTION 'resolution too complex' USING ERRCODE = 'M2002';
    END IF;
    v_has_access := FALSE;
    -- Userset subject handling
    IF position('#' in p_subject_id) > 0 THEN
        -- Case 1: Self-referential userset check
        IF (p_subject_type = 'agent_instance' AND substring(p_subject_id from 1 for position('#' in p_subject_id) - 1) = p_object_id) THEN
        SELECT INTO v_userset_check 1
    WHERE substring(p_subject_id from position('#' in p_subject_id) + 1) IN ('can_update')
    LIMIT 1;
        IF v_userset_check = 1 THEN
        RETURN 1;
    END IF;
    END IF;
    END IF;
    IF NOT (v_has_access) THEN
        -- Recursive access path via project -> can_manage
        IF EXISTS (
    SELECT 1
    FROM melange_tuples AS link
    WHERE (link.object_type = 'agent_instance' AND link.relation IN ('project') AND link.object_id = p_object_id AND "public"."check_permission_internal"(p_subject_type, p_subject_id, 'can_manage', link.subject_type, link.subject_id, p_visited || ARRAY[v_key]) = 1 AND link.subject_type IN ('project'))
    ) THEN
        v_has_access := TRUE;
    END IF;
    END IF;
    IF v_has_access THEN
        RETURN 1;
    END IF;
    RETURN 0;
END;
$$ LANGUAGE plpgsql STABLE COST 1000
SET search_path = 'public';


