-- Generated list_objects function for agent_attachment.instance
-- Features: Direct
CREATE OR REPLACE FUNCTION "public"."list_agent_attachment_instance_obj"(
    p_subject_type TEXT,
    p_subject_id TEXT,
    p_limit INT DEFAULT NULL,
    p_after TEXT DEFAULT NULL
) RETURNS TABLE(object_id TEXT, next_cursor TEXT) ROWS 100 AS $$
BEGIN
    RETURN QUERY
        WITH base_results AS (
            -- Direct tuple lookup with simple closure relations
                -- Type guard: only return results if subject type is in allowed subject types
                SELECT DISTINCT t.object_id
                FROM melange_tuples AS t
                WHERE (t.object_type = 'agent_attachment' AND t.relation IN ('instance') AND t.subject_type = p_subject_type AND p_subject_type IN ('agent_instance') AND (t.subject_id = p_subject_id AND NOT (t.subject_id = '*')))
                UNION
