-- Generated list_subjects function for agent_attachment.instance
-- Features: Direct
CREATE OR REPLACE FUNCTION "public"."list_agent_attachment_instance_sub"(
    p_object_id TEXT,
    p_subject_type TEXT,
    p_limit INT DEFAULT NULL,
    p_after TEXT DEFAULT NULL
) RETURNS TABLE(subject_id TEXT, next_cursor TEXT) ROWS 100 AS $$
DECLARE
    v_filter_type TEXT;
    v_filter_relation TEXT;
BEGIN
    -- Check if subject_type is a userset filter (e.g., "document#viewer")
    IF position('#' in p_subject_type) > 0 THEN
        v_filter_type := substring(p_subject_type from 1 for position('#' in p_subject_type) - 1);
        v_filter_relation := substring(p_subject_type from position('#' in p_subject_type) + 1);
        RETURN QUERY
        WITH base_results AS (
            -- Userset filter: find userset tuples that match and return normalized references
                SELECT DISTINCT split_part(t.subject_id, '#', 1) || '#' || v_filter_relation AS subject_id
		FROM melange_tuples AS t
		WHERE (t.object_type = 'agent_attachment' AND t.relation IN ('instance') AND t.object_id = p_object_id AND t.subject_type = v_filter_type AND position('#' in t.subject_id) > 0 AND (substring(t.subject_id from position('#' in t.subject_id) + 1) = v_filter_relation OR EXISTS (
                SELECT 1
                FROM (VALUES ('agent_attachment', 'can_execute', 'can_execute'), ('agent_attachment', 'can_manage', 'can_manage'), ('agent_attachment', 'can_read', 'can_read'), ('agent_attachment', 'instance', 'instance'), ('agent_attachment', 'repository', 'repository'), ('agent_instance', 'agent_configure', 'agent_configure'), ('agent_instance', 'agent_execute', 'agent_execute'), ('agent_instance', 'agent_inspect', 'agent_inspect'), ('agent_instance', 'agent_pause', 'agent_pause'), ('agent_instance', 'agent_recover', 'agent_recover'), ('agent_instance', 'agent_update', 'agent_update'), ('agent_instance', 'can_execute', 'can_execute'), ('agent_instance', 'can_grant_agent_capability', 'can_grant_agent_capability'), ('agent_instance', 'can_manage', 'can_manage'), ('agent_instance', 'can_read', 'can_read'), ('agent_instance', 'can_recover', 'can_recover'), ('agent_instance', 'can_update', 'can_update'), ('agent_instance', 'can_use_release', 'can_use_release'), ('agent_instance', 'project', 'project'), ('agent_instance', 'release_agent', 'release_agent')) AS subj_c(object_type, relation, satisfying_relation)
                WHERE (subj_c.object_type = v_filter_type AND subj_c.relation = substring(t.subject_id from position('#' in t.subject_id) + 1) AND subj_c.satisfying_relation = v_filter_relation)
                )) AND "public"."check_permission_internal"(v_filter_type, t.subject_id, 'instance', 'agent_attachment', p_object_id, ARRAY[]::TEXT[]) = 1)
                UNION
                -- Self-candidate: when filter type matches object type
                -- e.g., querying document:1.viewer with filter document#writer
                -- should return document:1#writer if writer satisfies the relation
                SELECT p_object_id || '#' || v_filter_relation AS subject_id
		WHERE (v_filter_type = 'agent_attachment' AND EXISTS (
                SELECT 1
                FROM (VALUES ('agent_attachment', 'can_execute', 'can_execute'), ('agent_attachment', 'can_manage', 'can_manage'), ('agent_attachment', 'can_read', 'can_read'), ('agent_attachment', 'instance', 'instance'), ('agent_attachment', 'repository', 'repository'), ('agent_instance', 'agent_configure', 'agent_configure'), ('agent_instance', 'agent_execute', 'agent_execute'), ('agent_instance', 'agent_inspect', 'agent_inspect'), ('agent_instance', 'agent_pause', 'agent_pause'), ('agent_instance', 'agent_recover', 'agent_recover'), ('agent_instance', 'agent_update', 'agent_update'), ('agent_instance', 'can_execute', 'can_execute'), ('agent_instance', 'can_grant_agent_capability', 'can_grant_agent_capability'), ('agent_instance', 'can_manage', 'can_manage'), ('agent_instance', 'can_read', 'can_read'), ('agent_instance', 'can_recover', 'can_recover'), ('agent_instance', 'can_update', 'can_update'), ('agent_instance', 'can_use_release', 'can_use_release'), ('agent_instance', 'project', 'project'), ('agent_instance', 'release_agent', 'release_agent')) AS c(object_type, relation, satisfying_relation)
                WHERE (c.object_type = 'agent_attachment' AND c.relation = 'instance' AND c.satisfying_relation = v_filter_relation)
                ))
        ),
        paged AS (
            SELECT br.subject_id
            FROM base_results br
            WHERE p_after IS NULL OR (
                -- Compound comparison for wildcard-first ordering:
                -- (is_not_wildcard, subject_id) > (cursor_is_not_wildcard, cursor)
                (CASE WHEN br.subject_id = '*' THEN 0 ELSE 1 END, br.subject_id) >
                (CASE WHEN p_after = '*' THEN 0 ELSE 1 END, p_after)
            )
            ORDER BY (CASE WHEN br.subject_id = '*' THEN 0 ELSE 1 END), br.subject_id
            LIMIT CASE WHEN p_limit IS NULL THEN NULL ELSE p_limit + 1 END
        ),
        returned AS (
            SELECT p.subject_id FROM paged p
            ORDER BY (CASE WHEN p.subject_id = '*' THEN 0 ELSE 1 END), p.subject_id
            LIMIT p_limit
        ),
        next AS (
            SELECT CASE
                WHEN p_limit IS NOT NULL AND (SELECT count(*) FROM paged) > p_limit
                THEN (SELECT r.subject_id FROM returned r
                      ORDER BY (CASE WHEN r.subject_id = '*' THEN 0 ELSE 1 END) DESC, r.subject_id DESC
                      LIMIT 1)
            END AS next_cursor
        )
        SELECT r.subject_id, n.next_cursor
        FROM returned r
        CROSS JOIN next n;
    ELSE
        -- Guard: return empty if subject type is not allowed by the model
        IF p_subject_type NOT IN ('agent_instance') THEN
        RETURN;
    END IF;
        -- Regular subject type (no userset filter)
        RETURN QUERY
        WITH base_results AS (
            -- Path 1: Direct tuple lookup with simple closure relations
                SELECT DISTINCT t.subject_id
                FROM melange_tuples AS t
                WHERE (t.object_type = 'agent_attachment' AND t.relation IN ('instance') AND t.object_id = p_object_id AND t.subject_type = p_subject_type AND position('#' in t.subject_id) = 0 AND t.subject_id <> '*')
        ),
        paged AS (
            SELECT br.subject_id
            FROM base_results br
