    p_object_id TEXT,
    p_subject_type TEXT,
    p_limit INT DEFAULT NULL,
    p_after TEXT DEFAULT NULL
) RETURNS TABLE(subject_id TEXT, next_cursor TEXT) ROWS 100 AS $$
DECLARE
    v_filter_type TEXT;
    v_filter_relation TEXT;
BEGIN
    -- Check if subject_type is a userset filter (e.g., "document#viewer")
    IF position('#' in p_subject_type) > 0 THEN
        v_filter_type := substring(p_subject_type from 1 for position('#' in p_subject_type) - 1);
        v_filter_relation := substring(p_subject_type from position('#' in p_subject_type) + 1);
        RETURN QUERY
        WITH base_results AS (
            -- Userset filter: find userset tuples that match and return normalized references
                SELECT DISTINCT split_part(t.subject_id, '#', 1) || '#' || v_filter_relation AS subject_id
		FROM melange_tuples AS t
		WHERE (t.object_type = 'project' AND t.relation IN ('agent_execute') AND t.object_id = p_object_id AND t.subject_type = v_filter_type AND position('#' in t.subject_id) > 0 AND (substring(t.subject_id from position('#' in t.subject_id) + 1) = v_filter_relation OR EXISTS (
                SELECT 1
                FROM (VALUES ('agent_instance', 'agent_configure', 'agent_configure'), ('agent_instance', 'agent_execute', 'agent_execute'), ('agent_instance', 'agent_inspect', 'agent_inspect'), ('agent_instance', 'agent_pause', 'agent_pause'), ('agent_instance', 'agent_recover', 'agent_recover'), ('agent_instance', 'agent_update', 'agent_update'), ('agent_instance', 'can_execute', 'can_execute'), ('agent_instance', 'can_grant_agent_capability', 'can_grant_agent_capability'), ('agent_instance', 'can_manage', 'can_manage'), ('agent_instance', 'can_read', 'can_read'), ('agent_instance', 'can_recover', 'can_recover'), ('agent_instance', 'can_update', 'can_update'), ('agent_instance', 'can_use_release', 'can_use_release'), ('agent_instance', 'project', 'project'), ('agent_instance', 'release_agent', 'release_agent'), ('project', 'agent_configure', 'agent_configure'), ('project', 'agent_execute', 'agent_execute'), ('project', 'agent_inspect', 'agent_inspect'), ('project', 'agent_pause', 'agent_pause'), ('project', 'agent_recover', 'agent_recover'), ('project', 'agent_update', 'agent_update'), ('project', 'brokered_secret_binder', 'brokered_secret_binder'), ('project', 'can_accept_secret_import', 'can_accept_secret_import'), ('project', 'can_accept_secret_import', 'secret_manager'), ('project', 'can_bind_brokered_secret', 'brokered_secret_binder'), ('project', 'can_bind_brokered_secret', 'can_bind_brokered_secret'), ('project', 'can_bind_brokered_secret', 'secret_manager'), ('project', 'can_bind_raw_secret', 'can_bind_raw_secret'), ('project', 'can_bind_raw_secret', 'raw_secret_binder'), ('project', 'can_bind_raw_secret', 'secret_manager'), ('project', 'can_delete', 'can_delete'), ('project', 'can_grant_agent_capability', 'can_grant_agent_capability'), ('project', 'can_grant_agent_capability', 'capability_granter'), ('project', 'can_inspect_secrets', 'can_inspect_secrets'), ('project', 'can_inspect_secrets', 'secret_manager'), ('project', 'can_manage', 'can_manage'), ('pr