                -- should return document:1#writer if writer satisfies the relation
                SELECT p_object_id || '#' || v_filter_relation AS subject_id
		WHERE (v_filter_type = 'project' AND EXISTS (
                SELECT 1
                FROM (VALUES ('agent_instance', 'agent_configure', 'agent_configure'), ('agent_instance', 'agent_execute', 'agent_execute'), ('agent_instance', 'agent_inspect', 'agent_inspect'), ('agent_instance', 'agent_pause', 'agent_pause'), ('agent_instance', 'agent_recover', 'agent_recover'), ('agent_instance', 'agent_update', 'agent_update'), ('agent_instance', 'can_execute', 'can_execute'), ('agent_instance', 'can_grant_agent_capability', 'can_grant_agent_capability'), ('agent_instance', 'can_manage', 'can_manage'), ('agent_instance', 'can_read', 'can_read'), ('agent_instance', 'can_recover', 'can_recover'), ('agent_instance', 'can_update', 'can_update'), ('agent_instance', 'can_use_release', 'can_use_release'), ('agent_instance', 'project', 'project'), ('agent_instance', 'release_agent', 'release_agent'), ('project', 'agent_configure', 'agent_configure'), ('project', 'agent_execute', 'agent_execute'), ('project', 'agent_inspect', 'agent_inspect'), ('project', 'agent_pause', 'agent_pause'), ('project', 'agent_recover', 'agent_recover'), ('project', 'agent_update', 'agent_update'), ('project', 'brokered_secret_binder', 'brokered_secret_binder'), ('project', 'can_accept_secret_import', 'can_accept_secret_import'), ('project', 'can_accept_secret_import', 'secret_manager'), ('project', 'can_bind_brokered_secret', 'brokered_secret_binder'), ('project', 'can_bind_brokered_secret', 'can_bind_brokered_secret'), ('project', 'can_bind_brokered_secret', 'secret_manager'), ('project', 'can_bind_raw_secret', 'can_bind_raw_secret'), ('project', 'can_bind_raw_secret', 'raw_secret_binder'), ('project', 'can_bind_raw_secret', 'secret_manager'), ('project', 'can_delete', 'can_delete'), ('project', 'can_grant_agent_capability', 'can_grant_agent_capability'), ('project', 'can_grant_agent_capability', 'capability_granter'), ('project', 'can_inspect_secrets', 'can_inspect_secrets'), ('project', 'can_inspect_secrets', 'secret_manager'), ('project', 'can_manage', 'can_manage'), ('project', 'can_manage', 'maintainer'), ('project', 'can_manage_secret_grants', 'can_manage_secret_grants'), ('project', 'can_manage_secret_grants', 'secret_manager'), ('project', 'can_purge_secrets', 'can_purge_secrets'), ('project', 'can_purge_secrets', 'secret_manager'), ('project', 'can_read', 'can_read'), ('project', 'can_read', 'maintainer'), ('project', 'can_revoke_secrets', 'can_revoke_secrets'), ('project', 'can_revoke_secrets', 'secret_manager'), ('project', 'can_rotate_secrets', 'can_rotate_secrets'), ('project', 'can_rotate_secrets', 'secret_manager'), ('project', 'can_write', 'can_write'), ('project', 'can_write', 'maintainer'), ('project', 'can_write_secret_value', 'can_write_secret_value'), ('project', 'can_write_secret_value', 'secret_manager'), ('project', 'capability_granter', 'capability_granter'), ('project', 'maintainer', 'maintainer'), ('project', 'organization', 'organization'), ('project', 'raw_secret_binder', 'raw_secret_binder'), ('project', 'secret_manager', 'secret_manager')) AS c(object_type, relation, satisfying_relation)
                WHERE (c.object_type = 'project' AND c.relation = 'agent_execute' AND c.satisfying_relation = v_filter_relation)
                ))
        ),
        paged AS (
            SELECT br.subject_id
            FROM base_results br
            WHERE p_after IS NULL OR (
                -- Compound comparison for wildcard-first ordering:
                -- (is_not_wildcard, subject_id) > (cursor_is_not_wildcard, cursor)
                (CASE WHEN br.subject_id = '*' THEN 0 ELSE 1 END, br.subject_id) >
                (CASE WHEN p_after = '*' THEN 0 ELSE 1 END, p_after)
