ger'), ('project', 'agent_configure', 'agent_configure'), ('project', 'agent_execute', 'agent_execute'), ('project', 'agent_inspect', 'agent_inspect'), ('project', 'agent_pause', 'agent_pause'), ('project', 'agent_recover', 'agent_recover'), ('project', 'agent_update', 'agent_update'), ('project', 'brokered_secret_binder', 'brokered_secret_binder'), ('project', 'can_accept_secret_import', 'can_accept_secret_import'), ('project', 'can_accept_secret_import', 'secret_manager'), ('project', 'can_bind_brokered_secret', 'brokered_secret_binder'), ('project', 'can_bind_brokered_secret', 'can_bind_brokered_secret'), ('project', 'can_bind_brokered_secret', 'secret_manager'), ('project', 'can_bind_raw_secret', 'can_bind_raw_secret'), ('project', 'can_bind_raw_secret', 'raw_secret_binder'), ('project', 'can_bind_raw_secret', 'secret_manager'), ('project', 'can_delete', 'can_delete'), ('project', 'can_grant_agent_capability', 'can_grant_agent_capability'), ('project', 'can_grant_agent_capability', 'capability_granter'), ('project', 'can_inspect_secrets', 'can_inspect_secrets'), ('project', 'can_inspect_secrets', 'secret_manager'), ('project', 'can_manage', 'can_manage'), ('project', 'can_manage', 'maintainer'), ('project', 'can_manage_secret_grants', 'can_manage_secret_grants'), ('project', 'can_manage_secret_grants', 'secret_manager'), ('project', 'can_purge_secrets', 'can_purge_secrets'), ('project', 'can_purge_secrets', 'secret_manager'), ('project', 'can_read', 'can_read'), ('project', 'can_read', 'maintainer'), ('project', 'can_revoke_secrets', 'can_revoke_secrets'), ('project', 'can_revoke_secrets', 'secret_manager'), ('project', 'can_rotate_secrets', 'can_rotate_secrets'), ('project', 'can_rotate_secrets', 'secret_manager'), ('project', 'can_write', 'can_write'), ('project', 'can_write', 'maintainer'), ('project', 'can_write_secret_value', 'can_write_secret_value'), ('project', 'can_write_secret_value', 'secret_manager'), ('project', 'capability_granter', 'capability_gra