ty_granter'), ('project', 'can_inspect_secrets', 'can_inspect_secrets'), ('project', 'can_inspect_secrets', 'secret_manager'), ('project', 'can_manage', 'can_manage'), ('project', 'can_manage', 'maintainer'), ('project', 'can_manage_secret_grants', 'can_manage_secret_grants'), ('project', 'can_manage_secret_grants', 'secret_manager'), ('project', 'can_purge_secrets', 'can_purge_secrets'), ('project', 'can_purge_secrets', 'secret_manager'), ('project', 'can_read', 'can_read'), ('project', 'can_read', 'maintainer'), ('project', 'can_revoke_secrets', 'can_revoke_secrets'), ('project', 'can_revoke_secrets', 'secret_manager'), ('project', 'can_rotate_secrets', 'can_rotate_secrets'), ('project', 'can_rotate_secrets', 'secret_manager'), ('project', 'can_write', 'can_write'), ('project', 'can_write', 'maintainer'), ('project', 'can_write_secret_value', 'can_write_secret_value'), ('project', 'can_write_secret_value', 'secret_manager'), ('project', 'capability_granter', 'capability_granter'), ('project', 'maintainer', 'maintainer'), ('project', 'organization', 'organization'), ('project', 'raw_secret_binder', 'raw_secret_binder'), ('project', 'secret_manager', 'secret_manager')) AS c(object_type, relation, satisfying_relation)
