-- Routes to specialized functions for all known type/relation pairs
CREATE OR REPLACE FUNCTION "public"."check_permission"(
    p_subject_type TEXT,
    p_subject_id TEXT,
    p_permission TEXT,
    p_object_type TEXT,
    p_object_id TEXT
) RETURNS INTEGER AS $$
    SELECT "public"."check_permission_internal"(p_subject_type, p_subject_id, p_permission, p_object_type, p_object_id, ARRAY[]::TEXT[]);
$$ LANGUAGE sql STABLE;


