		SELECT r.idx::INTEGER, CASE
            WHEN (r.subject_type = 'agent_instance' AND position('#' in r.subject_id) > 0 AND split_part(r.subject_id, '#', 1) = r.object_id AND substring(r.subject_id from position('#' in r.subject_id) + 1) IN ('agent_execute')) THEN 1
            WHEN EXISTS (
    SELECT 1
