    WHERE (t.subject_type = r.subject_type AND t.subject_id = r.subject_id AND t.relation = 'agent_execute' AND t.object_type = 'agent_instance' AND t.object_id = r.object_id AND r.subject_type IN ('agent_instance'))
    ) THEN 1
