-- ============================================================
-- Explain Dispatcher
-- ============================================================

-- Generated internal dispatcher for explain_permission
-- Routes (object_type, relation) to specialised explain_* functions
-- Returns a no-entry Trace JSONB when the pair is unknown so callers
-- never see NULL
CREATE OR REPLACE FUNCTION "public"."explain_permission_internal"(
    p_subject_type TEXT,
    p_subject_id TEXT,
    p_relation TEXT,
    p_object_type TEXT,
    p_object_id TEXT,
    p_visited TEXT [] DEFAULT ARRAY[]::TEXT[],
    p_max_nodes INTEGER DEFAULT NULL
) RETURNS JSONB AS $$
BEGIN
    -- Depth limit check shared with check_permission_internal
    IF array_length(p_visited, 1) >= 25 THEN
        RAISE EXCEPTION 'resolution too complex' USING ERRCODE = 'M2002';
    END IF;
    IF p_object_type = 'agent_attachment' THEN
        IF p_relation = 'instance' THEN
        RETURN "public"."explain_agent_attachment_instance"(p_subject_type, p_subject_id, p_object_id, p_visited, p_max_nodes);
    END IF;
        IF p_relation = 'repository' THEN
        RETURN "public"."explain_agent_attachment_repository"(p_subject_type, p_subject_id, p_object_id, p_visited, p_max_nodes);
    END IF;
        IF p_relation = 'can_manage' THEN
        RETURN "public"."explain_agent_attachment_can_manage"(p_subject_type, p_subject_id, p_object_id, p_visited, p_max_nodes);
    END IF;
        IF p_relation = 'can_execute' THEN
        RETURN "public"."explain_agent_attachment_can_execute"(p_subject_type, p_subject_id, p_object_id, p_visited, p_max_nodes);
    END IF;
        IF p_relation = 'can_read' THEN
        RETURN "public"."explain_agent_attachment_can_read"(p_subject_type, p_subject_id, p_object_id, p_visited, p_max_nodes);
    END IF;
        RETURN jsonb_build_object(
        'object', (p_object_type || ':' || p_object_id),
        'relation', p_relation,
        'subject', (p_subject_type || ':' || p_subject_id),
        'result', false,
        'root', jsonb_build_object('type', 'union', 'label', 'explain not yet supported for this (object_type, relation) — no generated explain function for the requested pair. Confirm the pair exists in the migrated schema.', 'children', '[]'::jsonb, 'result', false),
        'truncated', false,
        'node_count', 1);
    END IF;
    IF p_object_type = 'agent_instance' THEN
        IF p_relation = 'agent_configure' THEN
        RETURN "public"."explain_agent_instance_agent_configure"(p_subject_type, p_subject_id, p_object_id, p_visited, p_max_nodes);
    END IF;
        IF p_relation = 'agent_execute' THEN
        RETURN "public"."explain_agent_instance_agent_execute"(p_subject_type, p_subject_id, p_object_id, p_visited, p_max_nodes);
    END IF;
        IF p_relation = 'agent_inspect' THEN
        RETURN "public"."explain_agent_instance_agent_inspect"(p_subject_type, p_subject_id, p_object_id, p_visited, p_max_nodes);
    END IF;
        IF p_relation = 'agent_pause' THEN
        RETURN "public"."explain_agent_instance_agent_pause"(p_subject_type, p_subject_id, p_object_id, p_visited, p_max_nodes);
    END IF;
        IF p_relation = 'agent_recover' THEN
        RETURN "public"."explain_agent_instance_agent_recover"(p_subject_type, p_subject_id, p_object_id, p_visited, p_max_nodes);
    END IF;
        IF p_relation = 'agent_update' THEN
        RETURN "public"."explain_agent_instance_agent_update"(p_subject_type, p_subject_id, p_object_id, p_visited, p_max_nodes);
    END IF;
        IF p_relation = 'project' THEN
        RETURN "public"."explain_agent_instance_project"(p_subject_type, p_subject_id, p_object_id, p_visited, p_max_nodes);
    END IF;
        IF p_relation = 'release_agent' THEN
        RETURN "public"."explain_agent_instance_release_agent"(p_subject_type, p_subject_id, p_object_id, p_visited, p_max_nodes);
    END IF;
        IF p_relation = 'can_grant_agent_capability' THEN
        RETURN "public"."explain_agent_instance_can_grant_agent_capability"(p_subject_type, p_subject_id, p_object_id, p_visited, p_max_nodes);
    END IF;
        IF p_relation = 'can_manage' THEN
        RETURN "public"."explain_agent_instance_can_manage"(p_subject_type, p_subject_id, p_object_id, p_visited, p_max_nodes);
    END IF;
        IF p_relation = 'can_recover' THEN
        RETURN "public"."explain_agent_instance_can_recover"(p_subject_type, p_subject_id, p_object_id, p_visited, p_max_nodes);
    END IF;
